import { beforeEach, vi } from 'vitest';

// Mock fetch for API calls during client tests.
// In test environment there is no backend server, so we intercept
// the specific endpoints the app uses and return valid mock data.
// The passthrough target is captured once at module load: capturing it
// inside beforeEach grabs the previous test's spy (vi.spyOn returns the
// existing spy), making the default branch recurse on itself as soon as
// a test fetches a URL outside the mocked set.
const originalFetch = globalThis.fetch.bind(globalThis);

beforeEach(() => {
	vi.spyOn(globalThis, 'fetch').mockImplementation(
		async (input: RequestInfo | URL, init?: RequestInit) => {
			const url = typeof input === 'string' ? input : input instanceof URL ? input.href : input.url;

			// Mock server props endpoint
			if (url.includes('/server')) {
				return new Response(
					JSON.stringify({
						git_branch: 'test',
						git_commit: 'test',
						mode: 'router',
						version: 'test'
					}),
					{ headers: { 'Content-Type': 'application/json' }, status: 200 }
				);
			}

			// Mock models list endpoint
			if (/\/v1\/models|\/models\b/.test(url)) {
				return new Response(
					JSON.stringify({
						data: [
							{
								created: 0,
								id: 'test-model.gguf',
								in_cache: false,
								meta: {},
								object: 'model',
								owned_by: 'llamacpp',
								path: 'models/test-model.gguf',
								status: { value: 'unloaded' }
							}
						],
						models: [
							{
								details: {},
								model: 'test-model.gguf',
								name: 'Test Model'
							}
						],
						object: 'list'
					}),
					{ headers: { 'Content-Type': 'application/json' }, status: 200 }
				);
			}

			// Mock /props endpoint (used for modalities)
			if (url.includes('/props')) {
				return new Response(
					JSON.stringify({
						default_generation_settings: { n_ctx: 2048 }
					}),
					{ headers: { 'Content-Type': 'application/json' }, status: 200 }
				);
			}

			// Mock /tools endpoint (used for built-in tools list)
			if (url.includes('/tools')) {
				return new Response(JSON.stringify([]), {
					headers: { 'Content-Type': 'application/json' },
					status: 200
				});
			}

			// Default: use real fetch
			return originalFetch(input, init);
		}
	);
});

import { CONFIG_LOCALSTORAGE_KEY } from '$lib/constants';
import { settingsStore } from '$lib/stores/settings/index.svelte';
import { validateApiKey } from '$lib/utils/api-key-validation';
import { beforeEach, describe, expect, it } from 'vitest';

function fakeFetch(status: number, capture: { auth?: string | null } = {}) {
	return (async (_url: RequestInfo | URL, init?: RequestInit) => {
		capture.auth = (init?.headers as Record<string, string>)?.['Authorization'] ?? null;

		return new Response(status === 200 ? '{}' : 'Unauthorized', { status });
	}) as typeof globalThis.fetch;
}

const is401 = (err: unknown) =>
	typeof err === 'object' && err !== null && 'status' in err && err.status === 401;

describe('api key validation surfaces the splash', () => {
	beforeEach(() => {
		localStorage.removeItem(CONFIG_LOCALSTORAGE_KEY);
		settingsStore.initialize();
	});

	it('keyed server, no stored key: throws 401 so the splash shows (onboarding)', async () => {
		await expect(validateApiKey(fakeFetch(401))).rejects.toSatisfy(is401);
	});

	it('keyed server, wrong stored key: throws 401 so the splash shows', async () => {
		settingsStore.updateConfig('apiKey', 'wrong-key');
		await expect(validateApiKey(fakeFetch(401))).rejects.toSatisfy(is401);
	});

	it('open server, no stored key: passes silently', async () => {
		await expect(validateApiKey(fakeFetch(200))).resolves.toBeUndefined();
	});

	it('valid stored key: passes and sends the bearer header', async () => {
		settingsStore.updateConfig('apiKey', 'sk-good');
		const capture: { auth?: string | null } = {};

		await expect(validateApiKey(fakeFetch(200, capture))).resolves.toBeUndefined();
		expect(capture.auth).toBe('Bearer sk-good');
	});
});

/**
 * DatabaseService - IndexedDB persistence for conversations, messages and groups
 *
 * Thin Dexie layer over the conversations/messages/groups tables: CRUD, tree
 * navigation (descendants, reparenting) and cascading deletes. No reactive
 * state; consumed by conversationsStore, groupsStore and the chat flows.
 */

import {
	IDXDB_STORE_SCHEMAS,
	IDXDB_STORES_V1,
	IDXDB_TABLES,
	IDXDB_VERSION,
	STORAGE_APP_NAME
} from '$lib/constants';
import { MessageRole } from '$lib/enums';
import type { McpServerOverride } from '$lib/types/database';
import type { ExportedConversation } from '$lib/types/database';
import type { Group } from '$lib/types/groups';
import { filterByLeafNodeId, findDescendantMessages, uuid } from '$lib/utils';
import Dexie, { type EntityTable } from 'dexie';

class LlamaUiDatabase extends Dexie {
	[IDXDB_TABLES.conversations]!: EntityTable<DatabaseConversation, string>;
	[IDXDB_TABLES.groups]!: EntityTable<Group, 'id'>;
	[IDXDB_TABLES.messages]!: EntityTable<DatabaseMessage, string>;

	constructor() {
		super(STORAGE_APP_NAME);

		this.version(1).stores(IDXDB_STORES_V1);
		this.version(IDXDB_VERSION).stores({
			[IDXDB_TABLES.groups]: IDXDB_STORE_SCHEMAS.groups
		});
	}
}

const db = new LlamaUiDatabase();

export class DatabaseService {
	/**
	 * Deletes multiple conversations in a single transaction. Each deleted
	 * conversation has its direct children reparented to the nearest surviving
	 * ancestor (or promoted to top-level). Children also in `ids` are dropped
	 * entirely rather than reparented.
	 *
	 * @param ids - Conversation IDs to delete
	 */
	static async bulkDeleteConversations(ids: string[]): Promise<void> {
		const cleanIds = ids.filter((id): id is string => typeof id === 'string' && id.length > 0);

		if (cleanIds.length === 0) return;

		const idSet = new Set(cleanIds);

		await db.transaction(
			'rw',
			[db[IDXDB_TABLES.conversations], db[IDXDB_TABLES.messages]],
			async () => {
				// Pre-load each to-delete conversation so the per-id reparent
				// walk-up doesn't ping-pong the same ancestry chain.
				const prefetched = new Map<string, DatabaseConversation>();

				let frontier = [...cleanIds];

				const requested = new Set<string>(frontier);

				while (frontier.length > 0) {
					const fetched = await db[IDXDB_TABLES.conversations].bulkGet(frontier);

					frontier = [];
					for (let i = 0; i < fetched.length; i++) {
						const conv = fetched[i];

						if (!conv || !conv.id) continue;

						prefetched.set(conv.id, conv);
						const ancestor = conv.forkedFromConversationId;

						if (ancestor && !prefetched.has(ancestor) && !requested.has(ancestor)) {
							frontier.push(ancestor);
							requested.add(ancestor);
						}
					}
				}

				for (const id of cleanIds) {
					await this.reparentDirectChildren(id, idSet, prefetched);
				}

				await db[IDXDB_TABLES.conversations].bulkDelete(cleanIds);
				await db[IDXDB_TABLES.messages].where('convId').anyOf(cleanIds).delete();
			}
		);
	}

	/**
	 * Toggles the pinned status of each conversation in `ids` inside a single
	 * transaction. Treats `pinned === undefined` as `false`, matching the
	 * semantics of {@link toggleConversationPin} where `!undefined` evaluates
	 * to `true`. Returns the resulting pinned state for every id that was
	 * updated; missing ids are omitted from the map.
	 *
	 * @param ids - Conversation IDs to toggle
	 * @returns Map of id -> new pinned state
	 */
	static async bulkToggleConversationPins(ids: string[]): Promise<Map<string, boolean>> {
		const cleanIds = ids.filter((id): id is string => typeof id === 'string' && id.length > 0);
		const result = new Map<string, boolean>();

		if (cleanIds.length === 0) return result;

		await db.transaction('rw', db[IDXDB_TABLES.conversations], async () => {
			const convs = await db[IDXDB_TABLES.conversations].bulkGet(cleanIds);
			const updates: DatabaseConversation[] = [];

			for (let i = 0; i < cleanIds.length; i++) {
				const conv = convs[i];

				if (!conv) continue;

				const newPinned = !conv.pinned;

				updates.push({ ...conv, pinned: newPinned });
				result.set(cleanIds[i], newPinned);
			}

			if (updates.length === 0) return;

			await db[IDXDB_TABLES.conversations].bulkPut(updates);
		});

		return result;
	}

	/**
	 * Creates a new conversation.
	 *
	 * @param name - Name of the conversation
	 * @param fields - Optional extra fields (e.g. reasoningEffort)
	 * @returns The created conversation
	 */
	static async createConversation(
		name: string,
		fields?: Partial<Omit<DatabaseConversation, 'id' | 'name' | 'lastModified'>>
	): Promise<DatabaseConversation> {
		const conversation: DatabaseConversation = {
			currNode: '',
			id: uuid(),
			lastModified: Date.now(),
			name,
			...fields
		};

		await db[IDXDB_TABLES.conversations].add(conversation);

		return conversation;
	}

	/**
	 * Creates a new group.
	 *
	 * @returns The created group
	 */
	static async createGroup(group: Group): Promise<Group> {
		await db[IDXDB_TABLES.groups].add(group);

		return group;
	}

	/**
	 * Creates a new message branch by adding a message and updating parent/child relationships.
	 * Also updates the conversation's currNode to point to the new message.
	 *
	 * @param message - Message to add (without id)
	 * @param parentId - Parent message ID to attach to
	 * @returns The created message
	 */
	static async createMessageBranch(
		message: Omit<DatabaseMessage, 'id'>,
		parentId: string | null
	): Promise<DatabaseMessage> {
		return await db.transaction(
			'rw',
			[db[IDXDB_TABLES.conversations], db[IDXDB_TABLES.messages]],
			async () => {
				// Handle null parent (root message case)
				if (parentId !== null) {
					const parentMessage = await db[IDXDB_TABLES.messages].get(parentId);

					if (!parentMessage) {
						throw new Error(`Parent message ${parentId} not found`);
					}
				}

				const newMessage: DatabaseMessage = {
					...message,
					children: [],
					id: uuid(),
					parent: parentId,
					toolCalls: message.toolCalls ?? ''
				};

				await db[IDXDB_TABLES.messages].add(newMessage);

				// Update parent's children array if parent exists
				if (parentId !== null) {
					await this.addChildToParent(parentId, newMessage.id);
				}

				await this.updateConversation(message.convId, {
					currNode: newMessage.id
				});

				return newMessage;
			}
		);
	}

	/**
	 * Creates a root message for a new conversation.
	 * Root messages are not displayed but serve as the tree root for branching.
	 *
	 * @param convId - Conversation ID
	 * @returns The created root message
	 */
	static async createRootMessage(convId: string): Promise<string> {
		const rootMessage: DatabaseMessage = {
			children: [],
			content: '',
			convId,
			id: uuid(),
			parent: null,
			role: MessageRole.SYSTEM,
			timestamp: Date.now(),
			toolCalls: '',
			type: 'root'
		};

		await db[IDXDB_TABLES.messages].add(rootMessage);

		return rootMessage.id;
	}

	/**
	 * Creates a system prompt message for a conversation.
	 *
	 * @param convId - Conversation ID
	 * @param systemPrompt - The system prompt content (must be non-empty)
	 * @param parentId - Parent message ID (typically the root message)
	 * @returns The created system message
	 * @throws Error if systemPrompt is empty or the parent message does not exist
	 */
	static async createSystemMessage(
		convId: string,
		systemPrompt: string,
		parentId: string
	): Promise<DatabaseMessage> {
		const trimmedPrompt = systemPrompt.trim();

		if (!trimmedPrompt) {
			throw new Error('Cannot create system message with empty content');
		}

		return await db.transaction('rw', db[IDXDB_TABLES.messages], async () => {
			const parentMessage = await db[IDXDB_TABLES.messages].get(parentId);

			if (!parentMessage) {
				throw new Error(`Parent message ${parentId} not found`);
			}

			const systemMessage: DatabaseMessage = {
				children: [],
				content: trimmedPrompt,
				convId,
				id: uuid(),
				parent: parentId,
				role: MessageRole.SYSTEM,
				timestamp: Date.now(),
				type: MessageRole.SYSTEM
			};

			await db[IDXDB_TABLES.messages].add(systemMessage);
			await this.addChildToParent(parentId, systemMessage.id);

			return systemMessage;
		});
	}

	/**
	 * Deletes a conversation and all its messages.
	 *
	 * @param id - Conversation ID
	 */
	static async deleteConversation(
		id: string,
		options?: { deleteWithForks?: boolean }
	): Promise<void> {
		await db.transaction(
			'rw',
			[db[IDXDB_TABLES.conversations], db[IDXDB_TABLES.messages]],
			async () => {
				if (options?.deleteWithForks) {
					// Recursively collect all descendant IDs
					const idsToDelete: string[] = [];
					const queue = [id];

					while (queue.length > 0) {
						const parentId = queue.pop()!;
						const children = await db[IDXDB_TABLES.conversations]
							.filter((c) => c.forkedFromConversationId === parentId)
							.toArray();

						for (const child of children) {
							idsToDelete.push(child.id);
							queue.push(child.id);
						}
					}

					for (const forkId of idsToDelete) {
						await db[IDXDB_TABLES.conversations].delete(forkId);
						await db[IDXDB_TABLES.messages].where('convId').equals(forkId).delete();
					}
				} else {
					await this.reparentDirectChildren(id);
				}

				await db[IDXDB_TABLES.conversations].delete(id);
				await db[IDXDB_TABLES.messages].where('convId').equals(id).delete();
			}
		);
	}

	/**
	 * Deletes a group. Its conversations stay, out of any group.
	 *
	 * @param id - Group ID
	 */
	static async deleteGroup(id: string): Promise<void> {
		await db.transaction(
			'rw',
			[db[IDXDB_TABLES.groups], db[IDXDB_TABLES.conversations]],
			async () => {
				await db[IDXDB_TABLES.groups].delete(id);
				await db[IDXDB_TABLES.conversations]
					.filter((conversation) => conversation.groupId === id)
					.modify((conversation) => {
						delete conversation.groupId;
					});
			}
		);
	}

	/**
	 * Deletes a message and removes it from its parent's children array.
	 *
	 * @param messageId - ID of the message to delete
	 */
	static async deleteMessage(messageId: string): Promise<void> {
		await db.transaction('rw', db[IDXDB_TABLES.messages], async () => {
			const message = await db[IDXDB_TABLES.messages].get(messageId);

			if (!message) return;

			await this.removeChildFromParent(messageId);

			await db[IDXDB_TABLES.messages].delete(messageId);
		});
	}

	/**
	 * Deletes a message and all its descendant messages (cascading deletion).
	 * This removes the entire branch starting from the specified message.
	 *
	 * @param conversationId - ID of the conversation containing the message
	 * @param messageId - ID of the root message to delete (along with all descendants)
	 * @returns Array of all deleted message IDs
	 */
	static async deleteMessageCascading(
		conversationId: string,
		messageId: string
	): Promise<string[]> {
		return await db.transaction('rw', db[IDXDB_TABLES.messages], async () => {
			// Get all messages in the conversation to find descendants
			const allMessages = await db[IDXDB_TABLES.messages]
				.where('convId')
				.equals(conversationId)
				.toArray();
			const descendants = findDescendantMessages(allMessages, messageId);
			const allToDelete = [messageId, ...descendants];

			await this.removeChildFromParent(messageId);

			// Delete all messages in the branch
			await db[IDXDB_TABLES.messages].bulkDelete(allToDelete);

			return allToDelete;
		});
	}

	/**
	 * Forks a conversation at a specific message, creating a new conversation
	 * containing all messages from the root up to (and including) the target message.
	 *
	 * @param sourceConvId - The source conversation ID
	 * @param atMessageId - The message ID to fork at (the new conversation ends here)
	 * @param options - Fork options (name and whether to include attachments)
	 * @returns The newly created conversation
	 */
	static async forkConversation(
		sourceConvId: string,
		atMessageId: string,
		options: { name: string; includeAttachments: boolean }
	): Promise<DatabaseConversation> {
		return await db.transaction(
			'rw',
			[db[IDXDB_TABLES.conversations], db[IDXDB_TABLES.messages]],
			async () => {
				const sourceConv = await db[IDXDB_TABLES.conversations].get(sourceConvId);

				if (!sourceConv) {
					throw new Error(`Source conversation ${sourceConvId} not found`);
				}

				const allMessages = await db[IDXDB_TABLES.messages]
					.where('convId')
					.equals(sourceConvId)
					.toArray();
				const pathMessages = filterByLeafNodeId(
					allMessages,
					atMessageId,
					true
				) as DatabaseMessage[];

				if (pathMessages.length === 0) {
					throw new Error(`Could not resolve message path to ${atMessageId}`);
				}

				const idMap = new Map<string, string>();

				for (const msg of pathMessages) {
					idMap.set(msg.id, uuid());
				}

				const newConvId = uuid();
				const clonedMessages: DatabaseMessage[] = pathMessages.map((msg) => {
					const newId = idMap.get(msg.id)!;
					const newParent = msg.parent ? (idMap.get(msg.parent) ?? null) : null;
					const newChildren = msg.children
						.filter((childId: string) => idMap.has(childId))
						.map((childId: string) => idMap.get(childId)!);

					return {
						...msg,
						children: newChildren,
						convId: newConvId,
						extra: options.includeAttachments ? msg.extra : undefined,
						id: newId,
						parent: newParent
					};
				});
				const lastClonedMessage = clonedMessages[clonedMessages.length - 1];
				const newConv: DatabaseConversation = {
					currNode: lastClonedMessage.id,
					cwd: sourceConv.cwd,
					disabledToolCategories: sourceConv.disabledToolCategories
						? [...sourceConv.disabledToolCategories]
						: undefined,
					disabledTools: sourceConv.disabledTools ? [...sourceConv.disabledTools] : undefined,
					forkedFromConversationId: sourceConvId,
					groupId: sourceConv.groupId,
					id: newConvId,
					lastModified: Date.now(),
					mcpServerOverrides: sourceConv.mcpServerOverrides
						? sourceConv.mcpServerOverrides.map((o: McpServerOverride) => ({
								enabled: o.enabled,
								serverId: o.serverId
							}))
						: undefined,
					name: options.name
				};

				await db[IDXDB_TABLES.conversations].add(newConv);
				await db[IDXDB_TABLES.messages].bulkAdd(clonedMessages);

				return newConv;
			}
		);
	}

	/**
	 * Gets all conversations, sorted by last modified time (newest first).
	 *
	 * @returns Array of conversations
	 */
	static async getAllConversations(): Promise<DatabaseConversation[]> {
		return await db[IDXDB_TABLES.conversations].orderBy('lastModified').reverse().toArray();
	}

	/**
	 * Gets all groups, newest first by creation, the order new ones join the
	 * loaded list in, so a rename does not move a group on the next load.
	 *
	 * @returns Array of groups
	 */
	static async getAllGroups(): Promise<Group[]> {
		const groups = await db[IDXDB_TABLES.groups].toArray();

		return groups.sort((a, b) => b.createdAt - a.createdAt);
	}

	/**
	 * Gets a conversation by ID.
	 *
	 * @param id - Conversation ID
	 * @returns The conversation if found, otherwise undefined
	 */
	static async getConversation(id: string): Promise<DatabaseConversation | undefined> {
		return await db[IDXDB_TABLES.conversations].get(id);
	}

	/**
	 * Gets all messages in a conversation, sorted by timestamp (oldest first).
	 *
	 * @param convId - Conversation ID
	 * @returns Array of messages in the conversation
	 */
	static async getConversationMessages(convId: string): Promise<DatabaseMessage[]> {
		return await db[IDXDB_TABLES.messages].where('convId').equals(convId).sortBy('timestamp');
	}

	/**
	 * Loads multiple conversations with all of their messages in two bulk
	 * reads. Missing conversations are silently omitted from the result.
	 *
	 * @param convIds - Conversation IDs to load
	 * @returns Map of id -> { conv, messages }. Messages are sorted ascending by timestamp.
	 */
	static async getConversationsWithMessages(
		convIds: string[]
	): Promise<Map<string, ExportedConversation>> {
		const result = new Map<string, ExportedConversation>();
		const cleanIds = convIds.filter((id): id is string => typeof id === 'string' && id.length > 0);

		if (cleanIds.length === 0) return result;

		const [convs, allMessages] = await Promise.all([
			db[IDXDB_TABLES.conversations].bulkGet(cleanIds),
			db[IDXDB_TABLES.messages].where('convId').anyOf(cleanIds).toArray()
		]);
		const messagesByConv = new Map<string, DatabaseMessage[]>();

		for (const msg of allMessages) {
			const bucket = messagesByConv.get(msg.convId);

			if (bucket) bucket.push(msg);
			else messagesByConv.set(msg.convId, [msg]);
		}

		for (let i = 0; i < cleanIds.length; i++) {
			const conv = convs[i];

			if (!conv) continue;

			const messages = (messagesByConv.get(conv.id) ?? []).sort(
				(a, b) => a.timestamp - b.timestamp
			);

			result.set(conv.id, { conv, messages });
		}

		return result;
	}

	/**
	 * Imports multiple conversations and their messages.
	 * Skips conversations that already exist.
	 *
	 * @param data - Array of { conv, messages } objects
	 * @returns The conversations written to the database and the ones skipped
	 */
	static async importConversations(
		data: ExportedConversation[]
	): Promise<{ imported: DatabaseConversation[]; skipped: DatabaseConversation[] }> {
		const imported: DatabaseConversation[] = [];
		const skipped: DatabaseConversation[] = [];

		return await db.transaction(
			'rw',
			[db[IDXDB_TABLES.conversations], db[IDXDB_TABLES.groups], db[IDXDB_TABLES.messages]],
			async () => {
				for (const item of data) {
					const { messages } = item;
					const existing = await db[IDXDB_TABLES.conversations].get(item.conv.id);

					if (existing) {
						skipped.push(item.conv);

						continue;
					}

					const conv = { ...item.conv };
					const groupId = await DatabaseService.importGroup(item);

					if (groupId) conv.groupId = groupId;
					else delete conv.groupId;

					await db[IDXDB_TABLES.conversations].add(conv);
					for (const msg of messages) {
						await db[IDXDB_TABLES.messages].put(msg);
					}

					imported.push(conv);
				}

				return { imported, skipped };
			}
		);
	}

	/** Run `fn` in a readonly transaction over all tables. `fn` must await only Dexie calls, else the transaction commits early */
	static async readOnly<T>(
		fn: (tables: Pick<LlamaUiDatabase, keyof typeof IDXDB_TABLES>) => Promise<T>
	): Promise<T> {
		return db.transaction('r', [db[IDXDB_TABLES.conversations], db[IDXDB_TABLES.messages]], () =>
			fn(db)
		);
	}

	/**
	 * Puts conversations into a group, or out of any group when `groupId` is null.
	 * A conversation that joins a group is unpinned.
	 *
	 * @param ids - Conversation IDs
	 * @param groupId - Target group, null to take them out of their group
	 */
	static async setConversationsGroup(ids: string[], groupId: string | null): Promise<void> {
		await db[IDXDB_TABLES.conversations]
			.where('id')
			.anyOf(ids)
			.modify((conversation) => {
				if (groupId) {
					conversation.groupId = groupId;

					if (conversation.pinned) conversation.pinned = false;
				} else {
					delete conversation.groupId;
				}
			});
	}

	/**
	 * Toggles the pinned status of a conversation.
	 *
	 * @param id - Conversation ID
	 * @returns The new pinned status
	 */
	static async toggleConversationPin(id: string): Promise<boolean> {
		const conversation = await db[IDXDB_TABLES.conversations].get(id);

		if (!conversation) {
			throw new Error(`Conversation ${id} not found`);
		}

		const newPinnedState = !conversation.pinned;

		await this.updateConversation(id, { pinned: newPinnedState });

		return newPinnedState;
	}

	/**
	 * Updates a conversation. `lastModified` is never stamped implicitly;
	 * pass it in `updates` to bump the conversation in recency ordering.
	 *
	 * @param id - Conversation ID
	 * @param updates - Partial updates to apply
	 * @returns Promise that resolves when the conversation is updated
	 */
	static async updateConversation(
		id: string,
		updates: Partial<Omit<DatabaseConversation, 'id'>>
	): Promise<void> {
		await db[IDXDB_TABLES.conversations].update(id, updates);
	}

	/**
	 * Updates the conversation's current node (active branch).
	 * This determines which conversation path is currently being viewed.
	 *
	 * @param convId - Conversation ID
	 * @param nodeId - Message ID to set as current node
	 */
	static async updateCurrentNode(convId: string, nodeId: string): Promise<void> {
		await this.updateConversation(convId, {
			currNode: nodeId
		});
	}

	/**
	 * Updates a group. `updatedAt` is never stamped implicitly; pass it in
	 * `updates` to bump the group in recency ordering.
	 *
	 * @param id - Group ID
	 * @param updates - Partial group data to update
	 */
	static async updateGroup(id: string, updates: Partial<Omit<Group, 'id'>>): Promise<void> {
		await db[IDXDB_TABLES.groups].update(id, updates);
	}

	/**
	 * Updates a message.
	 *
	 * @param id - Message ID
	 * @param updates - Partial updates to apply
	 * @returns Promise that resolves when the message is updated
	 */
	static async updateMessage(
		id: string,
		updates: Partial<Omit<DatabaseMessage, 'id'>>
	): Promise<void> {
		await db[IDXDB_TABLES.messages].update(id, updates);
	}

	/**
	 * Appends a child id to a parent message's children array.
	 */
	private static async addChildToParent(parentId: string, childId: string): Promise<void> {
		const parent = await db[IDXDB_TABLES.messages].get(parentId);

		if (!parent) return;

		await db[IDXDB_TABLES.messages].update(parentId, {
			children: [...parent.children, childId]
		});
	}

	/**
	 * Finds the group an imported conversation goes into: the group of the same
	 * id, else one of the same name, else a new one named after the file's. A
	 * conversation whose group the file does not carry keeps it only if it exists.
	 * Runs inside the import transaction.
	 *
	 * @returns The group id, or undefined for none
	 */
	private static async importGroup(item: ExportedConversation): Promise<string | undefined> {
		const groups = db[IDXDB_TABLES.groups];

		if (!item.group) {
			const { groupId } = item.conv;

			return groupId && (await groups.get(groupId)) ? groupId : undefined;
		}

		const { id, name } = item.group;

		if (await groups.get(id)) return id;

		const sameName = await groups.where('name').equals(name).first();

		if (sameName) return sameName.id;

		const now = Date.now();

		await groups.add({ createdAt: now, id, name, updatedAt: now });

		return id;
	}

	/**
	 * Removes a child id from its parent message's children array.
	 */
	private static async removeChildFromParent(messageId: string): Promise<void> {
		const message = await db[IDXDB_TABLES.messages].get(messageId);

		if (!message?.parent) return;

		const parent = await db[IDXDB_TABLES.messages].get(message.parent);

		if (!parent) return;

		parent.children = parent.children.filter((childId: string) => childId !== messageId);
		await db[IDXDB_TABLES.messages].put(parent);
	}

	/**
	 * Reparents direct children of `parentId` to the nearest surviving
	 * ancestor (or promotes them to top-level when the immediate parent was
	 * top-level). Walking skips any ancestor listed in `excludeIds`, since
	 * those will be deleted in the same batch — leaving a grandchild pointing
	 * at an `excludeIds` entry would orphan it. Children whose own id is in
	 * `excludeIds` are dropped from the updates (the bulk-delete pass will
	 * remove them). `prefetched` may carry a pre-fetched ancestor map to
	 * avoid repeat reads inside a bulk transaction.
	 */
	private static async reparentDirectChildren(
		parentId: string,
		excludeIds: ReadonlySet<string> = new Set(),
		prefetched?: ReadonlyMap<string, DatabaseConversation>
	): Promise<void> {
		const conv = prefetched?.get(parentId) ?? (await db[IDXDB_TABLES.conversations].get(parentId));

		if (!conv) return;

		let newParent = conv.forkedFromConversationId;

		const visited = new Set<string>([parentId]);

		while (newParent && excludeIds.has(newParent)) {
			if (visited.has(newParent)) {
				newParent = undefined;

				break;
			}

			visited.add(newParent);
			const next =
				prefetched?.get(newParent) ?? (await db[IDXDB_TABLES.conversations].get(newParent));

			if (!next) {
				newParent = undefined;

				break;
			}

			newParent = next.forkedFromConversationId;
		}

		const directChildren = await db[IDXDB_TABLES.conversations]
			.filter((c) => c.forkedFromConversationId === parentId)
			.toArray();
		const updates: DatabaseConversation[] = [];

		for (const child of directChildren) {
			if (excludeIds.has(child.id)) continue;

			updates.push({ ...child, forkedFromConversationId: newParent });
		}

		if (updates.length === 0) return;

		await db[IDXDB_TABLES.conversations].bulkPut(updates);
	}
}

/**
 * MigrationService - Unified data migration hook
 *
 * Centralizes all data migrations (localStorage, IndexedDB, legacy formats)
 * into a single initialization point. Each migration copies data to the new
 * format WITHOUT deleting the old, and state is tracked in localStorage so
 * `runAllMigrations()` (called once at startup) never re-runs a completed
 * migration. All migrations are non-destructive for downgrade compatibility.
 */

import {
	CONFIG_LOCALSTORAGE_KEY,
	DB_APP_NAME_DEPRECATED,
	DISABLED_TOOL_KEYS_LOCALSTORAGE_KEY,
	IDXDB_STORES,
	IDXDB_STORES_V1,
	IDXDB_TABLES,
	IDXDB_VERSION,
	LEGACY_AGENTIC_REGEX,
	LEGACY_REASONING_TAGS,
	NEW_TO_DEPRECATED_MAP,
	SEARCH_CHATS_TOOL_KEY,
	SETTINGS_KEYS,
	STORAGE_APP_NAME,
	STORAGE_APP_NAME_DEPRECATED
} from '$lib/constants';
import { BooleanString, MessageRole } from '$lib/enums';
import type { McpServerOverride } from '$lib/types/database';
import { withSearchChatsDisabled } from '$lib/utils/search-chats';
import Dexie from 'dexie';

// Types

interface Migration {
	/** Unique identifier for this migration */
	id: string;
	/** Human-readable description */
	description: string;
	/** Run the migration forward (non-destructive - copies, doesn't delete) */
	run(): Promise<void>;
}

interface MigrationState {
	completed: string[];
	failed: string[];
	lastRun: string;
}

// Constants

const MIGRATION_STATE_KEY = `${STORAGE_APP_NAME}.migration-state`;
const MIGRATION_STATE_VERSION = 1;

// State Management

function getMigrationState(): MigrationState {
	try {
		const raw = localStorage.getItem(MIGRATION_STATE_KEY);

		if (!raw) return { completed: [], failed: [], lastRun: '' };

		const parsed = JSON.parse(raw);

		if (parsed.version !== MIGRATION_STATE_VERSION) {
			return { completed: [], failed: [], lastRun: '' };
		}

		return {
			completed: parsed.completed ?? [],
			failed: parsed.failed ?? [],
			lastRun: parsed.lastRun ?? ''
		};
	} catch {
		return { completed: [], failed: [], lastRun: '' };
	}
}

function saveMigrationState(state: MigrationState): void {
	localStorage.setItem(
		MIGRATION_STATE_KEY,
		JSON.stringify({
			version: MIGRATION_STATE_VERSION,
			...state,
			lastRun: new Date().toISOString()
		})
	);
}

function isMigrationCompleted(id: string): boolean {
	const state = getMigrationState();

	return state.completed.includes(id);
}

function markMigrationCompleted(id: string): void {
	const state = getMigrationState();

	if (!state.completed.includes(id)) {
		state.completed.push(id);
	}

	state.failed = state.failed.filter((f) => f !== id);
	saveMigrationState(state);
}

function markMigrationFailed(id: string): void {
	const state = getMigrationState();

	if (!state.failed.includes(id)) {
		state.failed.push(id);
	}

	saveMigrationState(state);
}

// Migration 1: LocalStorage Key Prefix (Non-Destructive)

const LOCALSTORAGE_MIGRATION_ID = 'localstorage-prefix-v1';
const localStorageMigration: Migration = {
	description: 'Copy localStorage keys from LlamaCppWebui to LlamaUi prefix (non-destructive)',
	id: LOCALSTORAGE_MIGRATION_ID,

	async run(): Promise<void> {
		// Non-destructive: copy to new key, but KEEP the old key
		for (const [newKey, deprecatedKey] of Object.entries(NEW_TO_DEPRECATED_MAP)) {
			// Only migrate if new key doesn't already exist
			const newValue = localStorage.getItem(newKey);

			if (newValue !== null) {
				if (import.meta.env.DEV && import.meta.env.VITE_DEBUG)
					console.log(`[Migration] localStorage: ${newKey} already exists, skipping`);

				continue;
			}

			const oldValue = localStorage.getItem(deprecatedKey);

			if (oldValue !== null) {
				localStorage.setItem(newKey, oldValue);

				// Keep old key for downgrade compatibility - DO NOT DELETE
				if (import.meta.env.DEV && import.meta.env.VITE_DEBUG) {
					console.log(
						`[Migration] localStorage: copied ${deprecatedKey} → ${newKey} (preserved old)`
					);
				}
			}
		}
	}
};

// Migration 2: IndexedDB Database Name (Non-Destructive)

// eslint-disable-next-line padding-line-between-statements -- comment header separates this const group
const IDXDB_MIGRATION_ID = 'idxdb-database-v1';
const idxdbMigration: Migration = {
	description: 'Copy IndexedDB from LlamacppWebui to LlamaUi database (non-destructive)',
	id: IDXDB_MIGRATION_ID,

	async run(): Promise<void> {
		const oldDbNames = await Dexie.getDatabaseNames();

		if (!oldDbNames.includes(DB_APP_NAME_DEPRECATED)) {
			if (import.meta.env.DEV && import.meta.env.VITE_DEBUG)
				console.log('[Migration] IndexedDB: no old database found, skipping');

			return;
		}

		// Check if new database already has data
		const newDb = new Dexie(STORAGE_APP_NAME);

		newDb.version(IDXDB_VERSION).stores(IDXDB_STORES);
		const existingConvs = await newDb.table(IDXDB_TABLES.conversations).count();

		if (existingConvs > 0) {
			if (import.meta.env.DEV && import.meta.env.VITE_DEBUG)
				console.log('[Migration] IndexedDB: new database already has data, skipping');

			return;
		}

		if (import.meta.env.DEV && import.meta.env.VITE_DEBUG)
			console.log('[Migration] IndexedDB: copying from', DB_APP_NAME_DEPRECATED);

		const oldDb = new Dexie(DB_APP_NAME_DEPRECATED);

		oldDb.version(1).stores(IDXDB_STORES_V1);

		const conversations = await oldDb.table(IDXDB_TABLES.conversations).toArray();
		const messages = await oldDb.table(IDXDB_TABLES.messages).toArray();

		if (conversations.length > 0) {
			await newDb.table(IDXDB_TABLES.conversations).bulkAdd(conversations);

			if (import.meta.env.DEV && import.meta.env.VITE_DEBUG)
				console.log(`[Migration] IndexedDB: copied ${conversations.length} conversations`);
		}

		if (messages.length > 0) {
			await newDb.table(IDXDB_TABLES.messages).bulkAdd(messages);

			if (import.meta.env.DEV && import.meta.env.VITE_DEBUG)
				console.log(`[Migration] IndexedDB: copied ${messages.length} messages`);
		}

		// Non-destructive: DO NOT delete old database - keep for downgrade compatibility
		if (import.meta.env.DEV && import.meta.env.VITE_DEBUG)
			console.log('[Migration] IndexedDB: preserved old database for downgrade compatibility');
	}
};

// Migration 3: Legacy Message Format

// eslint-disable-next-line padding-line-between-statements -- comment header separates this const group
const LEGACY_MESSAGE_MIGRATION_ID = 'legacy-message-format-v2';

interface ParsedTurn {
	textBefore: string;
	toolCalls: Array<{ name: string; args: string; result: string }>;
}

function parseLegacyToolCalls(content: string): ParsedTurn[] {
	const turns: ParsedTurn[] = [];
	const regex = new RegExp(LEGACY_AGENTIC_REGEX.COMPLETED_TOOL_CALL.source, 'g');

	let lastIndex = 0;
	let currentTurn: ParsedTurn = { textBefore: '', toolCalls: [] };
	let match;

	while ((match = regex.exec(content)) !== null) {
		const textBefore = content.slice(lastIndex, match.index).trim();

		if (textBefore && currentTurn.toolCalls.length > 0) {
			turns.push(currentTurn);
			currentTurn = { textBefore, toolCalls: [] };
		} else if (textBefore && currentTurn.toolCalls.length === 0) {
			currentTurn.textBefore = textBefore;
		}

		currentTurn.toolCalls.push({
			args: match[2],
			name: match[1],
			result: match[3].replace(/^\n+|\n+$/g, '')
		});

		lastIndex = match.index + match[0].length;
	}

	const remainingText = content.slice(lastIndex).trim();

	if (currentTurn.toolCalls.length > 0) {
		turns.push(currentTurn);
	}

	if (remainingText) {
		const cleanRemaining = remainingText
			.replace(LEGACY_AGENTIC_REGEX.AGENTIC_TOOL_CALL_OPEN, '')
			.trim();

		if (cleanRemaining) {
			turns.push({ textBefore: cleanRemaining, toolCalls: [] });
		}
	}

	if (turns.length === 0) {
		turns.push({ textBefore: content.trim(), toolCalls: [] });
	}

	return turns;
}

function extractLegacyReasoning(content: string): { reasoning: string; cleanContent: string } {
	let reasoning = '';
	let cleanContent = content;

	const re = new RegExp(LEGACY_AGENTIC_REGEX.REASONING_EXTRACT.source, 'g');

	let match;

	while ((match = re.exec(content)) !== null) {
		reasoning += match[1];
	}

	cleanContent = cleanContent
		.replace(new RegExp(LEGACY_AGENTIC_REGEX.REASONING_BLOCK.source, 'g'), '')
		.replace(LEGACY_AGENTIC_REGEX.REASONING_OPEN, '');

	return { cleanContent, reasoning };
}

function hasLegacyMarkers(content: string): boolean {
	return LEGACY_AGENTIC_REGEX.HAS_LEGACY_MARKERS.test(content);
}

let DatabaseService: typeof import('./database.service').DatabaseService | null = null;

async function getDatabaseService() {
	if (!DatabaseService) {
		const module = await import('./database.service');

		DatabaseService = module.DatabaseService;
	}

	return DatabaseService;
}

const legacyMessageMigration: Migration = {
	description: 'Migrate legacy marker-based messages to structured format',
	id: LEGACY_MESSAGE_MIGRATION_ID,

	async run(): Promise<void> {
		const db = await getDatabaseService();
		const conversations = await db.getAllConversations();

		let migratedCount = 0;

		for (const conv of conversations) {
			const allMessages = await db.getConversationMessages(conv.id);

			for (const message of allMessages) {
				if (message.role !== MessageRole.ASSISTANT) {
					if (message.content?.includes(LEGACY_REASONING_TAGS.START)) {
						const { cleanContent, reasoning } = extractLegacyReasoning(message.content);

						await db.updateMessage(message.id, {
							content: cleanContent.trim(),
							reasoningContent: reasoning || undefined
						});
						migratedCount++;
					}

					continue;
				}

				if (!hasLegacyMarkers(message.content ?? '')) continue;

				const { cleanContent, reasoning } = extractLegacyReasoning(message.content);
				const turns = parseLegacyToolCalls(cleanContent);

				let existingToolCalls: Array<{
					id: string;
					function?: { name: string; arguments: string };
				}> = [];

				if (message.toolCalls) {
					try {
						existingToolCalls = JSON.parse(message.toolCalls);
					} catch {
						// Ignore
					}
				}

				const firstTurn = turns[0];

				if (!firstTurn) continue;

				const firstTurnToolCalls = firstTurn.toolCalls.map((tc, i) => {
					const existing =
						existingToolCalls.find((e) => e.function?.name === tc.name) || existingToolCalls[i];

					return {
						function: { arguments: tc.args, name: tc.name },
						id: existing?.id || `legacy_tool_${i}`,
						type: 'function' as const
					};
				});

				await db.updateMessage(message.id, {
					content: firstTurn.textBefore,
					reasoningContent: reasoning || undefined,
					toolCalls: firstTurnToolCalls.length > 0 ? JSON.stringify(firstTurnToolCalls) : ''
				});

				let currentParentId = message.id;
				let toolCallIdCounter = existingToolCalls.length;

				for (let i = 0; i < firstTurn.toolCalls.length; i++) {
					const tc = firstTurn.toolCalls[i];
					const toolCallId = firstTurnToolCalls[i]?.id || `legacy_tool_${i}`;
					const toolMsg = await db.createMessageBranch(
						{
							children: [],
							content: tc.result,
							convId: conv.id,
							role: MessageRole.TOOL,
							timestamp: message.timestamp + i + 1,
							toolCallId,
							toolCalls: '',
							type: 'text'
						},
						currentParentId
					);

					currentParentId = toolMsg.id;
				}

				for (let turnIdx = 1; turnIdx < turns.length; turnIdx++) {
					const turn = turns[turnIdx];
					const turnToolCalls = turn.toolCalls.map((tc, i) => {
						const idx = toolCallIdCounter + i;
						const existing = existingToolCalls[idx];

						return {
							function: { arguments: tc.args, name: tc.name },
							id: existing?.id || `legacy_tool_${idx}`,
							type: 'function' as const
						};
					});

					toolCallIdCounter += turn.toolCalls.length;

					const assistantMsg = await db.createMessageBranch(
						{
							children: [],
							content: turn.textBefore,
							convId: conv.id,
							model: message.model,
							role: MessageRole.ASSISTANT,
							timestamp: message.timestamp + turnIdx * 100,
							toolCalls: turnToolCalls.length > 0 ? JSON.stringify(turnToolCalls) : '',
							type: 'text'
						},
						currentParentId
					);

					currentParentId = assistantMsg.id;

					for (let i = 0; i < turn.toolCalls.length; i++) {
						const tc = turn.toolCalls[i];
						const toolCallId = turnToolCalls[i]?.id || `legacy_tool_${toolCallIdCounter + i}`;
						const toolMsg = await db.createMessageBranch(
							{
								children: [],
								content: tc.result,
								convId: conv.id,
								role: MessageRole.TOOL,
								timestamp: message.timestamp + turnIdx * 100 + i + 1,
								toolCallId,
								toolCalls: '',
								type: 'text'
							},
							currentParentId
						);

						currentParentId = toolMsg.id;
					}
				}

				if (message.children.length > 0 && currentParentId !== message.id) {
					for (const childId of message.children) {
						const child = allMessages.find((m) => m.id === childId);

						if (!child) continue;

						if (child.role !== MessageRole.TOOL) {
							await db.updateMessage(childId, { parent: currentParentId });
						}
					}
					await db.updateMessage(message.id, { children: [] });
				}

				migratedCount++;
			}
		}

		if (import.meta.env.DEV && import.meta.env.VITE_DEBUG)
			console.log(`[Migration] Legacy messages: migrated ${migratedCount} messages`);
	}
};

// Migration 4: Theme Key (Non-Destructive)

// eslint-disable-next-line padding-line-between-statements -- comment header separates this const group
const THEME_MIGRATION_ID = 'theme-key-v1';
const themeMigration: Migration = {
	description: 'Copy standalone theme key to config object (non-destructive)',
	id: THEME_MIGRATION_ID,

	async run(): Promise<void> {
		const legacyTheme = localStorage.getItem('theme');

		if (legacyTheme === null) {
			if (import.meta.env.DEV && import.meta.env.VITE_DEBUG)
				console.log('[Migration] Theme: no legacy theme key found, skipping');

			return;
		}

		// Check if config already has theme
		const configRaw = localStorage.getItem(CONFIG_LOCALSTORAGE_KEY);
		const config = configRaw ? JSON.parse(configRaw) : {};

		if (SETTINGS_KEYS.THEME in config) {
			if (import.meta.env.DEV && import.meta.env.VITE_DEBUG)
				console.log('[Migration] Theme: config already has theme, skipping');

			return;
		}

		config[SETTINGS_KEYS.THEME] = legacyTheme;
		localStorage.setItem(CONFIG_LOCALSTORAGE_KEY, JSON.stringify(config));

		// Non-destructive: DO NOT delete legacy theme key - keep for downgrade compatibility
		if (import.meta.env.DEV && import.meta.env.VITE_DEBUG)
			console.log(`[Migration] Theme: copied standalone theme to config (preserved old key)`);
	}
};

// Migration Registry & Runner

// eslint-disable-next-line padding-line-between-statements -- comment header separates this const group
const CUSTOM_JSON_MIGRATION_ID = 'custom-json-key-v1';
const customJsonKeyMigration: Migration = {
	description: 'Copy legacy custom config key to customJson (non-destructive)',
	id: CUSTOM_JSON_MIGRATION_ID,

	async run(): Promise<void> {
		const configRaw = localStorage.getItem(CONFIG_LOCALSTORAGE_KEY);

		if (configRaw === null) return;

		const config = JSON.parse(configRaw);

		if (!('custom' in config)) return;

		if (SETTINGS_KEYS.CUSTOM_JSON in config) return;

		config[SETTINGS_KEYS.CUSTOM_JSON] = config.custom;
		localStorage.setItem(CONFIG_LOCALSTORAGE_KEY, JSON.stringify(config));

		// Non-destructive: keep the legacy custom key for downgrade compatibility
		if (import.meta.env.DEV && import.meta.env.VITE_DEBUG)
			console.log(`[Migration] Custom JSON: copied custom to customJson (preserved old key)`);
	}
};
const MCP_DEFAULT_ENABLED_MIGRATION_ID = 'mcp-default-enabled-to-config-v1';
const LEGACY_MCP_DEFAULT_ENABLED_KEY = `${STORAGE_APP_NAME}.mcpDefaultEnabled`;
const DEPRECATED_LEGACY_MCP_DEFAULT_ENABLED_KEY = `${STORAGE_APP_NAME_DEPRECATED}.mcpDefaultEnabled`;
const mcpDefaultEnabledMigration: Migration = {
	description:
		'Copy mcpDefaultEnabled localStorage key into settings config (preserves legacy keys)',
	id: MCP_DEFAULT_ENABLED_MIGRATION_ID,

	async run(): Promise<void> {
		const raw =
			localStorage.getItem(LEGACY_MCP_DEFAULT_ENABLED_KEY) ??
			localStorage.getItem(DEPRECATED_LEGACY_MCP_DEFAULT_ENABLED_KEY);

		// Legacy keys intentionally left in place so a downgrade keeps reading them.

		if (raw === null) {
			if (import.meta.env.DEV && import.meta.env.VITE_DEBUG)
				console.log('[Migration] MCP default enabled: no legacy key found, skipping');

			return;
		}

		const configRaw = localStorage.getItem(CONFIG_LOCALSTORAGE_KEY);
		const config = configRaw ? JSON.parse(configRaw) : {};

		// Don't overwrite an existing config entry — current data wins.
		if (MCP_DEFAULT_OVERRIDES_LEGACY_KEY in config) {
			if (import.meta.env.DEV && import.meta.env.VITE_DEBUG)
				console.log('[Migration] MCP default enabled: config already has overrides, skipping');

			return;
		}

		try {
			const parsed = JSON.parse(raw);

			if (!Array.isArray(parsed)) return;

			const valid = parsed.every(
				(o) =>
					typeof o === 'object' &&
					o !== null &&
					typeof (o as Record<string, unknown>).serverId === 'string' &&
					typeof (o as Record<string, unknown>).enabled === 'boolean'
			);

			if (!valid) return;
		} catch {
			return;
		}

		config[MCP_DEFAULT_OVERRIDES_LEGACY_KEY] = raw;
		localStorage.setItem(CONFIG_LOCALSTORAGE_KEY, JSON.stringify(config));

		if (import.meta.env.DEV && import.meta.env.VITE_DEBUG)
			console.log('[Migration] MCP default enabled: moved legacy key into config');
	}
};
const CONFIG_TYPES_MIGRATION_ID = 'config-type-normalization-v1';
const configTypesMigration: Migration = {
	description: 'Coerce legacy string-encoded booleans in persisted config to real booleans',
	id: CONFIG_TYPES_MIGRATION_ID,

	async run(): Promise<void> {
		const configRaw = localStorage.getItem(CONFIG_LOCALSTORAGE_KEY);

		if (configRaw === null) return;

		const config = JSON.parse(configRaw);

		let changed = false;

		// Pre-schema configs persisted booleans as "true"/"false" strings; the strict server
		// schema rejects them. No config string field holds exactly "true"/"false", so the
		// match is unambiguous.
		for (const key of Object.keys(config)) {
			if (config[key] === BooleanString.TRUE) {
				config[key] = true;
				changed = true;
			} else if (config[key] === BooleanString.FALSE) {
				config[key] = false;
				changed = true;
			}
		}

		if (changed) {
			localStorage.setItem(CONFIG_LOCALSTORAGE_KEY, JSON.stringify(config));
		}

		if (import.meta.env.DEV && import.meta.env.VITE_DEBUG)
			console.log(`[Migration] Config types: coerced string booleans (changed=${changed})`);
	}
};
const RENDER_KEYS_MIGRATION_ID = 'render-keys-unfold-v1';
const LEGACY_RENDER_RAW_TEXT_KEY = 'renderContentAsRawText';
const renderKeysMigration: Migration = {
	description: 'Unfold the single raw text render toggle onto the per-surface render keys',
	id: RENDER_KEYS_MIGRATION_ID,

	async run(): Promise<void> {
		const configRaw = localStorage.getItem(CONFIG_LOCALSTORAGE_KEY);

		if (configRaw === null) return;

		const config = JSON.parse(configRaw);

		if (!(LEGACY_RENDER_RAW_TEXT_KEY in config)) return;

		// The toggle carried user content and thinking at once and cannot say which surface
		// was chosen, so it only restores the user key and thinking keeps its own default.
		if (!(SETTINGS_KEYS.RENDER_USER_CONTENT_AS_MARKDOWN in config)) {
			config[SETTINGS_KEYS.RENDER_USER_CONTENT_AS_MARKDOWN] =
				config[LEGACY_RENDER_RAW_TEXT_KEY] !== true;
		}

		// Dropped rather than preserved: the two render keys and the toggle describe the same
		// surfaces, so leaving it behind would let a stale value fight the restored one.
		delete config[LEGACY_RENDER_RAW_TEXT_KEY];
		localStorage.setItem(CONFIG_LOCALSTORAGE_KEY, JSON.stringify(config));

		if (import.meta.env.DEV && import.meta.env.VITE_DEBUG)
			console.log('[Migration] Render keys: unfolded the raw text toggle');
	}
};
const LEGACY_MODEL_ORG_NAME_KEY = 'showModelOrgNameInTrigger';
const MODEL_ORG_NAME_KEY_MIGRATION_ID = 'model-org-name-key-v1';
/**
