const MCP_DEFAULT_OVERRIDES_LEGACY_KEY = `${STORAGE_APP_NAME}.mcpDefaultServerOverrides`;
const MCP_DEFAULT_OVERRIDES_MERGE_MIGRATION_ID = 'mcp-default-overrides-merge-v1';
/**
 * Folds `mcpDefaultServerOverrides` (the legacy "default for new chats" list,
 * JSON-encoded as `[{ serverId, enabled }, ...]`) into `mcpServers[i].enabled`.
 * The legacy override key is intentionally left in the config so a downgrade
 * keeps reading it. Runs after `mcpDefaultEnabledMigration` so any legacy
 * standalone overrides are already inside the config.
 */
const mcpDefaultOverridesMergeMigration: Migration = {
	description:
		'Merge mcpDefaultServerOverrides entries onto mcpServers[i].enabled (preserves legacy key)',
	id: MCP_DEFAULT_OVERRIDES_MERGE_MIGRATION_ID,

	async run(): Promise<void> {
		const configRaw = localStorage.getItem(CONFIG_LOCALSTORAGE_KEY);

		if (configRaw === null) return;

		const config = JSON.parse(configRaw);
		const raw = config[MCP_DEFAULT_OVERRIDES_LEGACY_KEY];

		if (typeof raw !== 'string' || raw.length === 0) {
			if (import.meta.env.DEV && import.meta.env.VITE_DEBUG)
				console.log('[Migration] MCP default overrides merge: nothing to merge');

			return;
		}

		let overrides: { serverId: string; enabled: boolean }[];

		try {
			const parsed = JSON.parse(raw);

			if (!Array.isArray(parsed)) return;

			overrides = parsed.filter(
				(o) =>
					typeof o === 'object' &&
					o !== null &&
					typeof (o as Record<string, unknown>).serverId === 'string' &&
					typeof (o as Record<string, unknown>).enabled === 'boolean'
			) as { serverId: string; enabled: boolean }[];
		} catch {
			return;
		}

		const serversRaw = config[SETTINGS_KEYS.MCP_SERVERS];

		let servers: { id: string; enabled?: boolean }[];

		try {
			servers = typeof serversRaw === 'string' ? JSON.parse(serversRaw) : [];
		} catch {
			return;
		}

		if (!Array.isArray(servers)) servers = [];

		let serversChanged = false;

		const knownIds = new Set(servers.map((s) => s.id));

		for (const override of overrides) {
			if (!knownIds.has(override.serverId)) continue;

			const index = servers.findIndex((s) => s.id === override.serverId);

			if (index >= 0 && servers[index].enabled !== override.enabled) {
				servers[index] = { ...servers[index], enabled: override.enabled };
				serversChanged = true;
			}
		}

		if (serversChanged) {
			config[SETTINGS_KEYS.MCP_SERVERS] = JSON.stringify(servers);
			localStorage.setItem(CONFIG_LOCALSTORAGE_KEY, JSON.stringify(config));
		}

		if (import.meta.env.DEV && import.meta.env.VITE_DEBUG)
			console.log(
				`[Migration] MCP default overrides merge: applied=${overrides.length} serversChanged=${serversChanged} (legacy key preserved)`
			);
	}
};
const MCP_SERVER_OVERRIDES_TO_TOOL_POLICY_MIGRATION_ID = 'mcp-server-overrides-to-tool-policy-v1';
const mcpServerOverridesToToolPolicyMigration: Migration = {
	description:
		'Seed per-conversation disabled tool keys from the global defaults and legacy per-conversation MCP server overrides (legacy field preserved)',
	id: MCP_SERVER_OVERRIDES_TO_TOOL_POLICY_MIGRATION_ID,

	async run(): Promise<void> {
		// The global disabled set used to apply to every conversation; it is now
		// the defaults seeded into newly created conversations, so existing rows
		// are seeded with it to keep their behavior unchanged.
		let defaults: string[] = [];

		try {
			const raw = localStorage.getItem(DISABLED_TOOL_KEYS_LOCALSTORAGE_KEY);

			if (raw) {
				const parsed: unknown = JSON.parse(raw);

				if (Array.isArray(parsed)) {
					defaults = parsed.filter((k): k is string => typeof k === 'string');
				}
			}
		} catch {
			// fall through with empty defaults so legacy overrides still migrate
		}

		const db = await getDatabaseService();
		const conversations = await db.getAllConversations();

		let migratedCount = 0;

		for (const conv of conversations) {
			// re-run safety: a row that already has a policy is left alone
			if (conv.disabledTools !== undefined) continue;

			// A legacy per-conversation server disable becomes a server-scoped tool
			// key (same format as toolsStore.getMcpServerToolsKey). Per-conversation
			// enables are dropped: the global server flag governs now.
			const serverGroupKeys = (conv.mcpServerOverrides ?? [])
				.filter((o: McpServerOverride) => !o.enabled)
				.map((o: McpServerOverride) => `mcp:${o.serverId}`);
			const disabledTools = [...new Set([...defaults, ...serverGroupKeys])];

			if (disabledTools.length === 0) continue;

			await db.updateConversation(conv.id, { disabledTools });
			migratedCount++;
		}

		if (import.meta.env.DEV && import.meta.env.VITE_DEBUG)
			console.log(
				`[Migration] MCP server overrides -> tool policy: updated ${migratedCount} conversations`
			);
	}
};
const SEARCH_CHATS_DEFAULT_DISABLED_MIGRATION_ID = 'search-chats-default-disabled-v1';
const searchChatsDefaultDisabledMigration: Migration = {
	description: 'Disable the search_chats tool by default, globally and in existing conversations',
	id: SEARCH_CHATS_DEFAULT_DISABLED_MIGRATION_ID,

	async run(): Promise<void> {
		// tool policy is a deny-list, so a new tool is enabled everywhere unless its key is added to the defaults and to each conversation
		let defaults: string[] = [];

		try {
			const raw = localStorage.getItem(DISABLED_TOOL_KEYS_LOCALSTORAGE_KEY);
			const parsed: unknown = raw ? JSON.parse(raw) : [];

			if (Array.isArray(parsed))
				defaults = parsed.filter((k): k is string => typeof k === 'string');
		} catch {
			// unreadable defaults are replaced below
		}

		localStorage.setItem(
			DISABLED_TOOL_KEYS_LOCALSTORAGE_KEY,
			JSON.stringify(withSearchChatsDisabled(defaults))
		);

		const db = await getDatabaseService();
		const conversations = await db.getAllConversations();

		for (const conv of conversations) {
			if (conv.disabledTools?.includes(SEARCH_CHATS_TOOL_KEY)) continue;

			await db.updateConversation(conv.id, {
				disabledTools: withSearchChatsDisabled(conv.disabledTools)
			});
		}
	}
};
const migrations: Migration[] = [
	localStorageMigration,
	idxdbMigration,
	legacyMessageMigration,
	themeMigration,
	customJsonKeyMigration,
	mcpDefaultEnabledMigration,
	mcpDefaultOverridesMergeMigration,
	configTypesMigration,
	renderKeysMigration,
	modelOrgNameKeyMigration,
	mcpServerOverridesToToolPolicyMigration,
	searchChatsDefaultDisabledMigration
];

export const MigrationService = {
	/**
	 * Get all registered migrations
	 */
	getMigrations(): Migration[] {
		return [...migrations];
	},

	/**
	 * Get current migration state
	 */
	getState(): MigrationState {
		return getMigrationState();
	},

	/**
	 * Check if a specific migration has been completed
	 */
	isCompleted(id: string): boolean {
		return isMigrationCompleted(id);
	},

	/**
	 * Reset migration state (use with caution - migrations will run again)
	 */
	resetState(): void {
		localStorage.removeItem(MIGRATION_STATE_KEY);

		if (import.meta.env.DEV && import.meta.env.VITE_DEBUG)
			console.log('[Migration] State reset - all migrations will run again');
	},

	/**
	 * Run all pending migrations (non-destructive - preserves legacy data)
	 * Should be called once at app initialization
	 */
	async runAllMigrations(): Promise<void> {
		const state = getMigrationState();

		if (import.meta.env.DEV && import.meta.env.VITE_DEBUG)
			console.log('[Migration] Starting migration run, state:', state);

		for (const migration of migrations) {
			if (isMigrationCompleted(migration.id)) {
				if (import.meta.env.DEV && import.meta.env.VITE_DEBUG)
					console.log(`[Migration] ${migration.id}: already completed, skipping`);

				continue;
			}

			try {
				if (import.meta.env.DEV && import.meta.env.VITE_DEBUG)
					console.log(`[Migration] ${migration.id}: running...`);

				await migration.run();
				markMigrationCompleted(migration.id);

				if (import.meta.env.DEV && import.meta.env.VITE_DEBUG)
					console.log(`[Migration] ${migration.id}: completed successfully`);
			} catch (error) {
				console.error(`[Migration] ${migration.id}: failed`, error);
				markMigrationFailed(migration.id);
			}
		}

		if (import.meta.env.DEV && import.meta.env.VITE_DEBUG)
			console.log('[Migration] All migrations complete');
	}
};

package com.example.llama

import android.view.LayoutInflater
import android.view.View
import android.view.ViewGroup
import android.widget.TextView
import androidx.recyclerview.widget.RecyclerView

data class Message(
    val id: String,
    val content: String,
    val isUser: Boolean
)

class MessageAdapter(
    private val messages: List<Message>
) : RecyclerView.Adapter<RecyclerView.ViewHolder>() {

    companion object {
        private const val VIEW_TYPE_USER = 1
        private const val VIEW_TYPE_ASSISTANT = 2
    }

    override fun getItemViewType(position: Int): Int {
        return if (messages[position].isUser) VIEW_TYPE_USER else VIEW_TYPE_ASSISTANT
    }

    override fun onCreateViewHolder(parent: ViewGroup, viewType: Int): RecyclerView.ViewHolder {
        val layoutInflater = LayoutInflater.from(parent.context)
        return if (viewType == VIEW_TYPE_USER) {
            val view = layoutInflater.inflate(R.layout.item_message_user, parent, false)
            UserMessageViewHolder(view)
        } else {
            val view = layoutInflater.inflate(R.layout.item_message_assistant, parent, false)
            AssistantMessageViewHolder(view)
        }
    }

    override fun onBindViewHolder(holder: RecyclerView.ViewHolder, position: Int) {
        val message = messages[position]
        if (holder is UserMessageViewHolder || holder is AssistantMessageViewHolder) {
            val textView = holder.itemView.findViewById<TextView>(R.id.msg_content)
            textView.text = message.content
        }
    }

    override fun getItemCount(): Int = messages.size

    class UserMessageViewHolder(view: View) : RecyclerView.ViewHolder(view)
    class AssistantMessageViewHolder(view: View) : RecyclerView.ViewHolder(view)
}

from __future__ import annotations

import json

from pathlib import Path
from typing import Any, Callable, Iterator, TYPE_CHECKING

if TYPE_CHECKING:
    from torch import Tensor

from .base import ModelBase, gguf, logger
from .qwen import Qwen3Model


def _is_vllm_decision2_checkpoint(dir_model: Path) -> bool:
    if not (dir_model / "config.json").is_file():
        return False
    with open(dir_model / "config.json", encoding="utf-8") as f:
        return json.load(f).get("decision_format") == "vllm-sr-decision"


@ModelBase.register_hparams_loader(_is_vllm_decision2_checkpoint)
def _load_vllm_decision2_hparams(dir_model: Path) -> dict[str, Any]:
    logger.info("gguf: detected vllm-sr Decision 2.0 checkpoint")
    with open(dir_model / "config.json", encoding="utf-8") as f:
        package = json.load(f)
    hparams = ModelBase.load_hparams((dir_model / package["backbone"]["config"]).parent, False, guess=False)
    hparams["architectures"] = ["VllmDecision2Model"]
    with open(dir_model / package["model_config"], encoding="utf-8") as f:
        hparams["decision"] = json.load(f)
    with open(dir_model / "score_bias.json", encoding="utf-8") as f:
        hparams["decision"]["score_bias"] = json.load(f)["offsets"]
    return hparams


@ModelBase.register("VllmDecision2Model")
@ModelBase.example("vllm-sr/Decision-2.0-Kai-0.6B")
class VllmDecision2Model(Qwen3Model):
    model_arch = gguf.MODEL_ARCH.VLLM_DECISION2

    # torch.nn.LayerNorm default, used by the head
    _HEAD_NORM_EPS = 1e-5

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        head = self.hparams["decision"]
        if head["architecture"] != "qwen3-text-endpoints-global-query-shared-bilinear-mlp" or head["head_variant"] != "shared":
            raise ValueError(f"unsupported decision head: {head['architecture']}")

    def index_tensors(self, *args, **kwargs) -> dict[str, Callable[[], Tensor]]:
        # the backbone weights are in their own directory
        dir_model, self.dir_model = self.dir_model, self.dir_model / "backbone"
        try:
            return super().index_tensors(*args, **kwargs)
        finally:
            self.dir_model = dir_model

    def get_tensors(self) -> Iterator[tuple[str, Tensor]]:
        yield from super().get_tensors()
        from safetensors.torch import load_file
        for name, data in load_file(self.dir_model / "decision_head.safetensors").items():
            yield "decision_head." + name, data

    def tensor_force_quant(self, name: str, new_name: str, bid: int | None, n_dims: int) -> gguf.GGMLQuantizationType | bool:
        # the head is computed in F32
        if new_name.startswith("decision."):
            return gguf.GGMLQuantizationType.F32
        return super().tensor_force_quant(name, new_name, bid, n_dims)

    def set_vocab(self):
        super().set_vocab()
        self.gguf_writer.add_chat_template([{"name": "systemone", "template": self._systemone_template()}])

    @classmethod
    def _systemone_template(cls) -> str:
        # prompt follows decision2/_vendor/dev2model/decision_model.py (segments) of the model repo
        # the pieces of the prompt are tokenized one by one, the server gives the text that separates them (sep)
        # and the text that starts the span of a question or of an option (mark_question, mark_option)
        # the head reads the last token of each option and the last token of the question
        # the start of an option is a piece of its own, so that the spans of two options are not joined
        # the keys of JSON objects are given in sorted order
        def text(value: str) -> str:
            return "{{ " + json.dumps(value) + " }}"

        def render(name: str) -> str:
            return "{{ " + name + " if " + name + " is string else " + name + " | tojson(separators=[',', ':']) }}"

        option = (
            "{% set d = o.description %}"
            "{% if q.type == 'noul' and d is none %}{% set d = 'Yes' if o.key == 'true' else 'No' %}{% endif %}"
            "{{ {'description': d, 'key': o.key} | tojson(separators=[',', ':']) }}"
        )
        return (
            "{% for q in questions %}"
            + text("Context:\n") + render("state")
            + text("\n\nTask type: ") + "{{ q.type }}" + text("\nQuestion:\n") + render("q.instructions") + text("\nOptions:")
            + "{% for o in q.options %}{{ sep }}" + text("\n<option>\n") + "{{ sep }}{{ mark_option }}" + option + text("\n</option>") + "{% endfor %}"
            + "{{ sep }}{{ mark_question }}" + text("\n\nSelect the single option best supported by the context and instructions.\nDecision:")
            + "{% endfor %}"
        )

    def set_gguf_parameters(self):
        super().set_gguf_parameters()
        self.gguf_writer.add_decision_type(gguf.DecisionType.VLLM_DECISION2)
        self.gguf_writer.add_layer_norm_eps(self._HEAD_NORM_EPS)
        for offsets in self.hparams["decision"]["score_bias"].values():
            self.gguf_writer.add_decision_score_bias(offsets)
